     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
     6	
     7	/**
     8	 * Normalizes the owner's telephone on create into E.164 form, mutating the validated request in
     9	 * place so later steps store and return the E.164 value. Spaces, dashes and brackets are stripped.
    10	 * A leading '+' and its country code are kept as given; otherwise country code '+61' is assumed and
    11	 * a single leading '0' is dropped from the national digits (so {@code 0412 345 678} becomes
    12	 * {@code +61412345678}). The result must carry 8 to 15 digits after the '+', and its national
    13	 * number (the digits after the country code) must match the length that country requires — '+61'
    14	 * needs 9 national digits, '+1' needs 10. Anything that cannot form valid E.164 is rejected 400 via
    15	 * {@link InvalidTelephoneException}.
    16	 */
    17	public class NormalizeOwnerTelephone {
    18	
    19	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
    20	        request.setTelephone(toE164(request.getTelephone()));
    21	    }
    22	
    23	    /**
    24	     * The single source of truth for what "same telephone" means: converts a raw telephone into its
    25	     * E.164 form. Spaces, dashes and brackets are removed; a leading '+' and country code are kept,
    26	     * otherwise '+61' is assumed and a single leading '0' is dropped from the national digits. The
    27	     * digits after the '+' must number 8 to 15, no other characters may remain, and the national
    28	     * number must have the length the country code requires ('+61' => 9, '+1' => 10). The E.164 value
    29	     * feeds the derived {@link org.springframework.samples.petclinic.model.Owner#getIdentityKey()
    30	     * identityKey} so the request side and stored owners are normalized identically.
    31	     *
    32	     * @throws InvalidTelephoneException if the value cannot form valid E.164.
    33	     */
    34	    static String toE164(String telephone) throws InvalidTelephoneException {
    35	        if (telephone == null) {
    36	            throw invalid();
    37	        }
    38	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
    39	        String digits;
    40	        if (cleaned.startsWith("+")) {
    41	            digits = cleaned.substring(1);
    42	        }
    43	        else {
    44	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
    45	            digits = "61" + national;
    46	        }
    47	        if (!digits.matches("\\d{8,15}")) {
    48	            throw invalid();
    49	        }
    50	        checkNationalLength(digits);
    51	        return "+" + digits;
    52	    }
    53	
    54	    /**
    55	     * Rejects a number whose national number (the digits after the country code) does not match the
    56	     * length that country code requires: '+61' => 9 national digits, '+1' => 10. Country codes not
    57	     * listed here are left to the generic 8-to-15 digit rule.
    58	     */
    59	    private static void checkNationalLength(String digits) throws InvalidTelephoneException {
    60	        String countryCode;
    61	        int requiredNationalLength;
    62	        if (digits.startsWith("61")) {
    63	            countryCode = "61";
    64	            requiredNationalLength = 9;
    65	        }
    66	        else if (digits.startsWith("1")) {
    67	            countryCode = "1";
    68	            requiredNationalLength = 10;
    69	        }
    70	        else {
    71	            return;
    72	        }
    73	        int nationalLength = digits.length() - countryCode.length();
    74	        if (nationalLength != requiredNationalLength) {
    75	            throw new InvalidTelephoneException("Telephone with country code '+" + countryCode
    76	                    + "' must have " + requiredNationalLength + " national digits, but had "
    77	                    + nationalLength);
    78	        }
    79	    }
    80	
    81	    private static InvalidTelephoneException invalid() {
    82	        return new InvalidTelephoneException(
    83	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
    84	    }
    85	}
