     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.Locale;
     4	
     5	import net.officefloor.plugin.variable.Val;
     6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     7	import org.springframework.samples.petclinic.rest.escalation.InvalidAddressException;
     8	
     9	/**
    10	 * Normalizes the owner's address on create, mutating the validated request in place so later
    11	 * steps persist and return the normalized value. The address is trimmed with internal whitespace
    12	 * runs collapsed to a single space, upper-cased, and common street-type abbreviations are expanded
    13	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Because address is a required
    14	 * field, an address that is blank after normalization is rejected 400 via
    15	 * {@link InvalidAddressException} — the required-field check now applies to the normalized form, so
    16	 * a whitespace-only value that passes the raw length constraint is still rejected here.
    17	 */
    18	public class NormalizeOwnerAddress {
    19	
    20	    public void service(@Val OwnerFieldsDto request) throws InvalidAddressException {
    21	        String normalized = normalize(request.getAddress());
    22	        if (normalized.isEmpty()) {
    23	            throw new InvalidAddressException("Address must not be blank after normalization");
    24	        }
    25	        request.setAddress(normalized);
    26	    }
    27	
    28	    /**
    29	     * The single source of truth for the normalized form of an address: trimmed with internal
    30	     * whitespace collapsed, upper-cased, and common street-type abbreviations expanded. Returns the
    31	     * empty string for a null or blank input. Shared with {@link AssignOwnerHousehold} so the request
    32	     * side and the shared household id are compared on identical normalized text.
    33	     */
    34	    static String normalize(String value) {
    35	        if (value == null) {
    36	            return "";
    37	        }
    38	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
    39	        if (collapsed.isEmpty()) {
    40	            return "";
    41	        }
    42	        String[] tokens = collapsed.split(" ");
    43	        StringBuilder sb = new StringBuilder(collapsed.length());
    44	        for (int i = 0; i < tokens.length; i++) {
    45	            if (i > 0) {
    46	                sb.append(' ');
    47	            }
    48	            sb.append(expand(tokens[i]));
    49	        }
    50	        return sb.toString();
    51	    }
    52	
    53	    private static String expand(String token) {
    54	        switch (token) {
    55	            case "ST":
    56	                return "STREET";
    57	            case "RD":
    58	                return "ROAD";
    59	            case "AVE":
    60	                return "AVENUE";
    61	            default:
    62	                return token;
    63	        }
    64	    }
    65	}
