     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.nio.charset.StandardCharsets;
     4	import java.security.MessageDigest;
     5	import java.security.NoSuchAlgorithmException;
     6	import java.util.ArrayList;
     7	import java.util.List;
     8	import java.util.Locale;
     9	
    10	import net.officefloor.plugin.variable.Val;
    11	import org.springframework.samples.petclinic.model.Owner;
    12	import org.springframework.samples.petclinic.repository.OwnerRepository;
    13	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
    14	
    15	/**
    16	 * Assigns a shared, stable {@code householdId} when the request opts in with
    17	 * {@code sharesHousehold=true} and an existing owner shares the same household. What counts
    18	 * as the same household — same lastName AND address, compared on their normalized forms — is
    19	 * single-sourced in {@link #sameHousehold}, so the household id assigned here feeds the derived
    20	 * {@link org.springframework.samples.petclinic.model.Owner#getIdentityKey() identityKey} and the
    21	 * duplicate check consistently. The identifier is derived deterministically from the
    22	 * normalized lastName and address, so every owner in one household receives the same value
    23	 * regardless of creation order. Both the joining owner and any matching existing owner that
    24	 * still lacks the id are stamped with it, so the household is linked on both sides. Runs
    25	 * after {@link BuildOwner} has created the entity and before {@link CheckOwnerIdentityUnique}
    26	 * (which sees the resolved {@code householdId}) and {@link SaveOwner} persists it. When the request
    27	 * does not opt in, or opts in but no existing owner shares the household, the id is left unset.
    28	 */
    29	public class AssignOwnerHousehold {
    30	
    31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
    32	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
    33	            return;
    34	        }
    35	        List<Owner> matches = new ArrayList<>();
    36	        String shared = null;
    37	        for (Owner existing : ownerRepository.findAll()) {
    38	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
    39	                continue;
    40	            }
    41	            if (sameHousehold(owner.getLastName(), owner.getAddress(),
    42	                    existing.getLastName(), existing.getAddress())) {
    43	                matches.add(existing);
    44	                if (shared == null && existing.getHouseholdId() != null) {
    45	                    shared = existing.getHouseholdId();
    46	                }
    47	            }
    48	        }
    49	        if (matches.isEmpty()) {
    50	            return;
    51	        }
    52	        if (shared == null) {
    53	            shared = deriveHouseholdId(normalize(owner.getLastName()),
    54	                    NormalizeOwnerAddress.normalize(owner.getAddress()));
    55	        }
    56	        owner.setHouseholdId(shared);
    57	        for (Owner existing : matches) {
    58	            if (existing.getHouseholdId() == null) {
    59	                existing.setHouseholdId(shared);
    60	                ownerRepository.save(existing);
    61	            }
    62	        }
    63	    }
    64	
    65	    /**
    66	     * The single source of truth for what "same household" means: identical lastName AND address.
    67	     * The lastName is compared case-insensitively with internal whitespace collapsed; the address is
    68	     * compared on its normalized form (see {@link NormalizeOwnerAddress#normalize}) so abbreviation,
    69	     * case and whitespace differences never split one household.
    70	     */
    71	    static boolean sameHousehold(String lastNameA, String addressA, String lastNameB, String addressB) {
    72	        return normalize(lastNameA).equals(normalize(lastNameB))
    73	                && NormalizeOwnerAddress.normalize(addressA).equals(NormalizeOwnerAddress.normalize(addressB));
    74	    }
    75	
    76	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
    77	    static String normalize(String value) {
    78	        if (value == null) {
    79	            return "";
    80	        }
    81	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    82	    }
    83	
    84	    /**
    85	     * Derives the stable household identifier {@code HH-<12 upper hex>} from the SHA-256 of the
    86	     * normalized {@code lastName|address}, so two owners in the same household compute the same id.
    87	     */
    88	    private static String deriveHouseholdId(String lastName, String address) {
    89	        try {
    90	            byte[] digest = MessageDigest.getInstance("SHA-256")
    91	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
    92	            StringBuilder sb = new StringBuilder(12);
    93	            for (int i = 0; i < 6; i++) {
    94	                sb.append(String.format("%02X", digest[i]));
    95	            }
    96	            return "HH-" + sb.toString().toUpperCase(Locale.ROOT);
    97	        }
    98	        catch (NoSuchAlgorithmException ex) {
    99	            throw new IllegalStateException("SHA-256 not available", ex);
   100	        }
   101	    }
   102	}

