   245	    }
   246	
   247	    /**
   248	     * The owner's region, derived at response time by preferring the postcode: the region whose
   249	     * fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099})
   250	     * contains {@link #postcode}, falling back to the fixed city-to-region table
   251	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) when the postcode is
   252	     * absent or in no known range, or {@code UNKNOWN} when neither resolves.
   253	     */
   254	    public String getLocality() {
   255	        String region = regionOfPostcode(this.postcode);
   256	        if (region == null) {
   257	            region = regionOf(this.city);
   258	        }
   259	        return region != null ? region : "UNKNOWN";
   260	    }
   261	
   262	    /**
   263	     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
   264	     * email is present, otherwise {@code PHONE}. Not persisted.
   265	     */
   266	    public String getContactPreference() {
   267	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
   268	    }
   269	
   270	    /**
   271	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
   272	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
   273	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
   274	     * digit from the right, subtracting 9 from any result over 9, and taking
   275	     * {@code (10 - sum % 10) % 10}. Not persisted.
   276	     */
   277	    public Integer getCheckDigit() {
   278	        if (this.customerCode == null) {
   279	            return null;
   280	        }
   281	        int sum = 0;
   282	        boolean dbl = true;
   283	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
   284	            char c = this.customerCode.charAt(i);
   285	            if (c < '0' || c > '9') {
   286	                continue;
   287	            }
   288	            int d = c - '0';
   289	            if (dbl) {
   290	                d *= 2;
   291	                if (d > 9) {
   292	                    d -= 9;
   293	                }
   294	            }
   295	            sum += d;
   296	            dbl = !dbl;
   297	        }
   298	        return (10 - (sum % 10)) % 10;
   299	    }
