   302	     * The single source of truth for an owner's identity: the derived key
   303	     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
   304	     * canonical E.164 form and the email lower-cased, so this key composes their canonical values;
   305	     * an absent email or householdId contributes an empty segment. Two owners are duplicates exactly
   306	     * when their whole identity keys are equal — differing in any one segment (for example two
   307	     * members of the same household with different telephones) yields different keys. Derived at
   308	     * response time and used by the create pipeline's single duplicate check; not persisted.
   309	     */
   310	    public String getIdentityKey() {
   311	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
   312	    }
   313	
   314	    private static String keyPart(String value) {
   315	        return value == null ? "" : value;
   316	    }
   317	
   318	    protected Set<Pet> getPetsInternal() {
   319	        if (this.pets == null) {
   320	            this.pets = new HashSet<>();
   321	        }
   322	        return this.pets;
   323	    }
   324	
   325	    protected void setPetsInternal(Set<Pet> pets) {
   326	        this.pets = pets;
   327	    }
