   329	    public List<Pet> getPets() {
   330	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
   331	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
   332	        return Collections.unmodifiableList(sortedPets);
   333	    }
   334	
   335	    public void setPets(List<Pet> pets) {
   336	        this.pets = new HashSet<>(pets);
   337	    }
   338	
   339	    public void addPet(Pet pet) {
   340	        getPetsInternal().add(pet);
   341	        pet.setOwner(this);
   342	    }
   343	
   344	    /**
