   356	     *
   357	     * @param name to test
   358	     * @return true if pet name is already in use
   359	     */
   360	    public Pet getPet(String name, boolean ignoreNew) {
   361	        name = name.toLowerCase();
   362	        for (Pet pet : getPetsInternal()) {
   363	            if (!ignoreNew || !pet.isNew()) {
   364	                String compName = pet.getName();
   365	                compName = compName.toLowerCase();
   366	                if (compName.equals(name)) {
   367	                    return pet;
   368	                }
   369	            }
   370	        }
   371	        return null;
   372	    }
   373	
   374	    public Pet getPet(Integer petId) {
   375	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
   376	    }
   377	
   378	    @Override
   379	    public String toString() {
   380	        return new ToStringCreator(this)
   381	
   382	            .append("id", this.getId())
   383	            .append("new", this.isNew())
   384	            .append("lastName", this.getLastName())
   385	            .append("firstName", this.getFirstName())
   386	            .append("address", this.address)
   387	            .append("city", this.city)
   388	            .append("telephone", this.telephone)
   389	            .append("email", this.email)
   390	            .toString();
   391	    }
   392	}
